package ml.peya.plugins.Utils;

/**
 * 数学関数ユーティリティ。
 */
public class LearnMath
{
    /**
     * sigmoid 関数。
     *
     * @param x 入力値。
     * @return sigmoid 値。
     */
    public static double sigmoid(double x)
    {
        return 1.0 / (1.0 + Math.exp(-x));
    }
}

package ml.peya.plugins.Utils;

/**
 * 波動値を生成するクラス。
 */
public class WaveCreator
{
    private final double min;
    private final double max;
    private final double speed;
    private double position = 0.0;

    /**
     * コンストラクタ。
     *
     * @param min   最小値。
     * @param max   最大値。
     * @param speed 速度。
     */
    public WaveCreator(double min, double max, double speed)
    {
        this.min = min;
        this.max = max;
        this.speed = speed;
    }

    /**
     * 波動値を取得。
     *
     * @param increment 増分。
     * @param reset     リセットするかどうか。
     * @return 波動値。
     */
    public double get(double increment, boolean reset)
    {
        if (reset)
        {
            position = 0.0;
        }
        position += increment * speed;
        double wave = Math.sin(position);
        return min + (wave + 1.0) / 2.0 * (max - min);
    }

    /**
     * 固定値（最大値）を取得。
     *
     * @return 最大値。
     */
    public double getStatic()
    {
        return max;
    }
}

package ml.peya.plugins.Utils;

import java.util.HashMap;
import java.util.Map;
import java.util.Random;

/**
 * 文字をリート語に変換するユーティリティ。
 */
public class LeetConverter
{
    private static final Map<Character, Character[]> leetMap = new HashMap<>();

    static
    {
        leetMap.put('a', new Character[]{'4', '@', '/\\', '^'});
        leetMap.put('b', new Character[]{'8', '6', '|3', '13'});
        leetMap.put('c', new Character[]{'(', '[', '<', '{'});
        leetMap.put('e', new Character[]{'3', '&', '[-'});
        leetMap.put('g', new Character[]{'9', '6', '&', '['});
        leetMap.put('i', new Character[]{'1', '!', '|', ']'});
        leetMap.put('l', new Character[]{'1', '|_', '][_', '|'});
        leetMap.put('o', new Character[]{'0', '()', '*', '[]'});
        leetMap.put('s', new Character[]{'5', '$', 'z', '§'});
        leetMap.put('t', new Character[]{'7', '+', '-|-', '\'}'});
        leetMap.put('z', new Character[]{'2', '7_', '≥', '~/_'});
    }

    private static final Random random = new Random();

    /**
     * 文字列をリート語に変換。
     *
     * @param input 入力文字列。
     * @return リート語変換後の文字列。
     */
    public static String convert(String input)
    {
        if (input == null || input.isEmpty())
        {
            return input;
        }

        StringBuilder result = new StringBuilder();
        for (char c : input.toLowerCase().toCharArray())
        {
            Character[] replacements = leetMap.get(c);
            if (replacements != null && random.nextBoolean())
            {
                result.append(replacements[random.nextInt(replacements.length)]);
            }
            else
            {
                result.append(c);
            }
        }
        return result.toString();
    }
}

